-- Codes HZ-0001 / PR-0001 generated by the database
CREATE SEQUENCE "found_item_code_seq";
CREATE SEQUENCE "lost_report_code_seq";

CREATE FUNCTION next_code(prefix text, seq regclass) RETURNS text 
LANGUAGE sql VOLATILE AS $$
  SELECT prefix || lpad(n::text, greatest(4, length(n::text)), '0')
  FROM (SELECT nextval(seq) AS n) s
$$;

